cd /home/daniel/ui-work/runs/202610271-to/sandbox/officehq-tanstack-officefloor/src/main/frontend/features
python3 - <<'EOF'
p='settings/settings.ts'; s=open(p).read()
s=s.replace("reviewSla: string; perms:","reviewSla: string; proofKinds: string; perms:",1)
s=s.replace("key !== 'entry-date' && key !== 'pot'","key !== 'entry-date' && key !== 'proof-kinds' && key !== 'pot'",1)
s=s.replace("| 'cap' | 'proof-threshold' |","| 'cap' | 'proof-threshold' | 'proof-kinds' |",1)
s=s.replace(" *  And the pot (two decimals; '' for none, not dated)"," *  And the proof kinds (comma separated receipt and photo; '' for none, not dated): a claim above the proof threshold\n *  needs a proof of each before it is settled or approved.\n *  And the pot (two decimals; '' for none, not dated)",1)
open(p,'w').write(s)
p='settings/settings.slot.tsx'; s=open(p).read()
s=s.replace("// The pot (two decimals, not dated; blank means none)","// The proof kinds (receipt and photo, comma separated, not dated; blank means none): while set, a claim above the\n// proof threshold needs a proof of each before it is settled or approved.\n// The pot (two decimals, not dated; blank means none)",1)
s=s.replace("  const [proofThreshold, setProofThreshold] = useState('');\n","  const [proofThreshold, setProofThreshold] = useState('');\n  const [proofKinds, setProofKinds] = useState('');\n",1)
s=s.replace("      setProofThreshold('');\n","      setProofThreshold('');\n      setProofKinds('');\n",1)
s=s.replace("'proof-threshold': proofThreshold,","'proof-threshold': proofThreshold, 'proof-kinds': proofKinds,",1)
old="""        now <span data-testid="setting-proof-threshold-current"><Fig>{data?.proofThreshold ?? ''}</Fig></span>{' '}
"""
assert old in s
s=s.replace(old,old+"""        <label>
          Proof kinds{' '}
          <input
            data-testid="setting-proof-kinds"
            placeholder="receipt,photo (blank: none)"
            value={proofKinds}
            onChange={(e) => {
              setProofKinds(e.target.value);
              touch('proof-kinds');
            }}
            // As the policy date: clearing an already blank field must still send the blank.
            onFocus={() => touch('proof-kinds')}
          />
        </label>{' '}
        now <span data-testid="setting-proof-kinds-current">{data?.proofKinds ?? ''}</span>{' '}
""",1)
s=s.replace("the rounding mode half-up or half-even, or blank.","the rounding mode half-up or half-even, or blank; the proof kinds receipt or photo, comma separated, or blank.",1)
open(p,'w').write(s)
EOF
grep -rn "proofThreshold" --include=*.ts --include=*.tsx .. | grep -v "features/settings" | head

